def compute(vars):
    shares = vars["v1"]
    exercise_price = vars["v2"]
    total_value = shares * exercise_price

    return {
        "value": total_value,
        "trace": {
            "shares": shares,
            "exercise_price_per_share": exercise_price,
            "total_value": total_value,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "currency"
            }
        }
    }
